import{readFileSync,writeFileSync,existsSync,realpathSync,openSync,readSync,closeSync}from'node:fs';import{createHash}from'node:crypto';
// Bound pin verification's temporary memory without omitting pre/post checks.
const hashBuffer=Buffer.allocUnsafe(65536);
function hash(path){
  const digest=createHash('sha256'),fd=openSync(path,'r');
  try{
    for(let size;(size=readSync(fd,hashBuffer,0,hashBuffer.length,null))!==0;){
      digest.update(size===hashBuffer.length?hashBuffer:hashBuffer.subarray(0,size));
    }
  }finally{closeSync(fd);}
  return digest.digest('hex');
}
const plan=JSON.parse(readFileSync(process.argv[2],'utf8')),result={schemaVersion:1,status:'RUNNING',cells:[]};
const ref=path=>({path:realpathSync(path),sha256:hash(path)}),save=()=>writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');
for(const cell of plan.cells){
 if(existsSync(cell.report)||existsSync(cell.report+'.physical.json'))throw Error('Existingactualreport '+cell.id);
 for(const[path,sha256]of Object.entries(plan.immutablePins))if(realpathSync(path)!==path||hash(path)!==sha256)throw Error('Immutablepreactivationdrift '+path);
 const beforeActivation=existsSync(plan.slot)?ref(plan.slot):null;writeFileSync(plan.slot,readFileSync(cell.source.path));const activated=ref(plan.slot);if(activated.sha256!==cell.source.sha256)throw Error('Activationbytesdiffer');
 const request=JSON.parse(readFileSync(cell.request.path,'utf8'));if(hash(cell.request.path)!==cell.request.sha256)throw Error('Requestdrift');for(const[path,sha256]of Object.entries({...request.pins,...request.inputs}))if(realpathSync(path)!==path||hash(path)!==sha256)throw Error('Activepre-rundrift '+path);
 console.log('START '+cell.id+' '+new Date().toISOString());const start=performance.now(),child=Bun.spawn(cell.command,{cwd:cell.cwd,stdout:'pipe',stderr:'pipe'}),[exitCode,stdout,stderr]=await Promise.all([child.exited,new Response(child.stdout).text(),new Response(child.stderr).text()]);
 const line=stderr.split('\n').find(x=>x.startsWith('HEAVY_GATE ')),guardian=line?JSON.parse(line.slice(11)):null,postActive=ref(plan.slot);let postPinsVerified=true;for(const[path,sha256]of Object.entries({...request.pins,...request.inputs}))if(realpathSync(path)!==path||hash(path)!==sha256)postPinsVerified=false;
 const passed=exitCode===0&&guardian?.status==='PASS'&&guardian.ownedTreeStopped&&postPinsVerified&&postActive.sha256===activated.sha256;result.cells.push({...cell,exitCode,elapsedMs:performance.now()-start,stdout,stderr,guardian,activation:{before:beforeActivation,active:activated,post:postActive,postPinsVerified},passed});save();console.log('FINISH '+cell.id+' '+(passed?'PASS':'FAIL')+' '+new Date().toISOString());if(!passed){result.status='FAILED_CELL_RETAINED';save();process.exit(exitCode||1);}
}
result.status='ALL_CELLS_FINISHED';save();console.log(JSON.stringify({status:result.status,cells:result.cells.length,output:plan.output}));
